 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Right){Close();return;}if(e.Button!=MouseButtons.Left)return;if(document!=null){if(HandleOptions(e.Location))return;int index=Hit(e.Location);if(index>=0){CommitText();ActionFor(ids[index]);return;}if(!selection.Contains(e.Location)){CommitText();return;}CommitText();if(tool=="text"){AddText(e.Location);return;}drawing=new ShotMark{Tool=tool,A=Local(e.Location),B=Local(e.Location),Color=ink,Width=stroke};drawing.Points.Add(drawing.A);Capture=true;return;}anchor=e.Location;selecting=true;Capture=true;selection=new Rectangle(e.Location,Size.Empty);Invalidate();}
